module tb;

    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to check outputs against expected values
    task check_output(input expected_z);
        begin
            #1; // Wait slightly after clock edge for combinatorial/sequential propagation
            if (z !== expected_z) begin
                $display("Time %0t: Mismatch! x=%b, z=%b, expected_z=%b", $time, x, z, expected_z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Test 1: Asynchronous Reset Test
        // Assert reset asynchronously
        areset = 1;
        #7;
        // In state A after reset. Test input x=0 -> z=0
        x = 0;
        #3;
        // Check output during reset (should be held or reset-dependent, but let's check after reset deassertion)

        // Deassert reset
        areset = 0;
        @(posedge clk);
        // State A, x=0 -> z=0, next state A
        check_output(1'b0);

        // Test 2: State A, x=1 -> z=1, next state B
        @(posedge clk);
        x = 1;
        check_output(1'b1);

        // Test 3: State B (reached after first 1), x=0 -> z=1, stays in B
        @(posedge clk);
        x = 0;
        check_output(1'b1);

        // Test 4: State B, x=1 -> z=0, stays in B
        @(posedge clk);
        x = 1;
        check_output(1'b0);

        // Test 5: State B, x=1 -> z=0, stays in B
        @(posedge clk);
        x = 1;
        check_output(1'b0);

        // Test 6: State B, x=0 -> z=1, stays in B
        @(posedge clk);
        x = 0;
        check_output(1'b1);

        // Test 7: Apply synchronous/asynchronous reset mid-stream
        areset = 1;
        #4;
        areset = 0;
        x = 0;
        @(posedge clk);
        // Back to state A, x=0 -> z=0
        check_output(1'b0);

        // Test 8: State A, x=1 -> z=1, next state B
        @(posedge clk);
        x = 1;
        check_output(1'b1);

        // Final delay before finish
        #10;

        // Self-checking final result
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
